using System;
public class HealthUpWithDefRelics : Item
{
	public static string staticID = "HealthUpWithDefRelics";
	private NumVarStatMod hpMod;
	private int hpInc = 10;
	private int defCount;
	protected override string ExtraInfo => "+ " + (int)hpMod.modValue;
	public HealthUpWithDefRelics()
	{
		ID = staticID;
		category = Category.Defense;
		hpMod = new NumVarStatMod(ID, 0f);
	}
	public override void Activate()
	{
		SetModStatus(givenStatus: true);
	}
	public override void Deactivate()
	{
		SetModStatus(givenStatus: false);
	}
	private void SetModStatus(bool givenStatus)
	{
		if (!(parentEntity == null))
		{
			ApplyMod(givenStatus);
			Inventory inventory = parentEntity.inventory;
			inventory.inventoryChangeEventHandler = (Inventory.ItemEventHandler)Delegate.Remove(inventory.inventoryChangeEventHandler, new Inventory.ItemEventHandler(OnInventoryChange));
			if (givenStatus)
			{
				Inventory inventory2 = parentEntity.inventory;
				inventory2.inventoryChangeEventHandler = (Inventory.ItemEventHandler)Delegate.Combine(inventory2.inventoryChangeEventHandler, new Inventory.ItemEventHandler(OnInventoryChange));
			}
		}
	}
	private void OnInventoryChange(Item givenItem, bool givenStatus)
	{
		if (parentEntity != null)
		{
			ApplyMod(givenStatus: true);
		}
	}
	private void ApplyMod(bool givenStatus)
	{
		if (givenStatus)
		{
			defCount = 0;
			foreach (Item value in parentEntity.inventory.itemDict.Values)
			{
				if (value == null)
				{
					continue;
				}
				if (value is GroupItem)
				{
					foreach (Item value2 in (value as GroupItem).itemInven.itemDict.Values)
					{
						if (IsDefenseItem(value2))
						{
							defCount++;
						}
					}
				}
				else if (IsDefenseItem(value))
				{
					defCount++;
				}
			}
			hpMod.modValue = hpInc * defCount;
		}
		parentEntity.health.healthStat.Modify(hpMod, givenStatus);
	}
	private bool IsDefenseItem(Item givenItem)
	{
		return givenItem != null && givenItem.category == Category.Defense;
	}
}
