using System;
public class HealthUpWithEmpowered : Item
{
	public static string staticID = "HealthUpWithEmpowered";
	private NumVarStatMod hpMod;
	private int hpInc = 10;
	private int empCount;
	protected override string ExtraInfo => "+ " + (int)hpMod.modValue;
	public HealthUpWithEmpowered()
	{
		ID = staticID;
		category = Category.Defense;
		hpMod = new NumVarStatMod(ID, hpInc);
	}
	public override void Activate()
	{
		SetModStatus(givenStatus: true);
	}
	public override void Deactivate()
	{
		SetModStatus(givenStatus: false);
	}
	private void SetModStatus(bool givenStatus)
	{
		if (SetParentAsPlayer())
		{
			Player player = parentPlayer;
			player.skillPickUpEventHandlers = (Player.SkillEventHandler)Delegate.Remove(player.skillPickUpEventHandlers, new Player.SkillEventHandler(OnSkillPickup));
			Player player2 = parentPlayer;
			player2.assignSkillSlotEventHandlers = (Player.AssignSkillSlotEventHandler)Delegate.Remove(player2.assignSkillSlotEventHandlers, new Player.AssignSkillSlotEventHandler(OnSkillAssign));
			if (givenStatus)
			{
				Player player3 = parentPlayer;
				player3.skillPickUpEventHandlers = (Player.SkillEventHandler)Delegate.Combine(player3.skillPickUpEventHandlers, new Player.SkillEventHandler(OnSkillPickup));
				Player player4 = parentPlayer;
				player4.assignSkillSlotEventHandlers = (Player.AssignSkillSlotEventHandler)Delegate.Combine(player4.assignSkillSlotEventHandlers, new Player.AssignSkillSlotEventHandler(OnSkillAssign));
				CalculateModValue();
			}
			ApplyMod(givenStatus);
		}
	}
	private void OnSkillPickup(Player.SkillState gs)
	{
		CalculateModValue();
	}
	private void OnSkillAssign(Player.SkillState ns = null, int ssn = 0)
	{
		CalculateModValue();
	}
	private void CalculateModValue()
	{
		if (parentPlayer == null)
		{
			return;
		}
		empCount = 0;
		for (int i = 0; i < parentPlayer.assignedSkills.Length; i++)
		{
			if (parentPlayer.assignedSkills[i] != null && parentPlayer.assignedSkills[i].IsEmpowered)
			{
				empCount++;
			}
		}
		if (parentPlayer.stockSkill != null && parentPlayer.stockSkill.IsEmpowered)
		{
			empCount++;
		}
		hpMod.modValue = hpInc * empCount;
		parentPlayer.health.healthStat.Modify(hpMod, addMod: true);
	}
	private void ApplyMod(bool givenStatus)
	{
		if (parentPlayer != null)
		{
			parentPlayer.health.healthStat.Modify(hpMod, givenStatus);
		}
	}
}
