	public override void Deactivate()
	{
		SetModStatus(givenStatus: false);
	}
	private void SetModStatus(bool givenStatus)
	{
		if (SetParentAsPlayer())
		{
			Player player = parentPlayer;
			player.assignSkillSlotEventHandlers = (Player.AssignSkillSlotEventHandler)Delegate.Remove(player.assignSkillSlotEventHandlers, new Player.AssignSkillSlotEventHandler(CalculateAndApplyMods));
			if (givenStatus)
			{
				CalculateAndApplyMods();
				Player player2 = parentPlayer;
				player2.assignSkillSlotEventHandlers = (Player.AssignSkillSlotEventHandler)Delegate.Combine(player2.assignSkillSlotEventHandlers, new Player.AssignSkillSlotEventHandler(CalculateAndApplyMods));
			}
			else
			{
				ApplyMods(givenStatus: false);
			}
		}
	}
	private void CalculateAndApplyMods(Player.SkillState givenSkill = null, int givenSlot = 0)
	{
		if (parentPlayer == null)
		{
			return;
		}
		int num = 0;
		for (int i = 0; i < parentPlayer.assignedSkills.Length; i++)
		{
			if (parentPlayer.assignedSkills[i] != null && parentPlayer.assignedSkills[i].isMovementSkill)
			{
				num++;
			}
		}
		healthMod.modValue = healthInc * num;
		ApplyMods(givenStatus: true);
	}
	private void ApplyMods(bool givenStatus)
	{
		if (parentPlayer != null)
		{
			parentPlayer.health.healthStat.Modify(healthMod, givenStatus);
		}
	}
}
