using System.Collections;
using UnityEngine;
public class IgnoreDeathChance : OnTakeDamageItem
{
	public static string staticID = "IgnoreDeathChance";
	private float ignoreChance = 1f;
	private BoolVarStatMod deathProofMod;
	private ChaosQuickStopwatch activeStopwatch;
	private bool itemHeld;
	protected override string ExtraInfo => PercentToStr(ignoreChance, "+");
	public IgnoreDeathChance()
	{
		ID = staticID;
		category = Category.Defense;
		destroyOnDrop = true;
		activateOnEvent = true;
		deathProofMod = new BoolVarStatMod(ID, newModValue: true);
		activeStopwatch = new ChaosQuickStopwatch(2.5f);
	}
	public override void SetHandlers(bool givenStatus)
	{
		if (SetParentAsPlayer())
		{
			base.SetHandlers(givenStatus);
			if (givenStatus)
			{
				itemHeld = true;
				SetItemBarStatus();
				return;
			}
			SetDeathProofStatus(parentPlayer, givenStatus: false);
			RemoveFromItemBar();
			itemHeld = false;
			parentPlayer.newItemNoticeUI.Display(TextManager.GetItemName(ID), IconManager.GetItemIcon(ID), null, isSkill: false, isSignature: false, isEmpowered: false, acquired: false);
		}
	}
	public override void OnTakeDamageEvent(AttackInfo givenAtkInfo, Entity givenEnt)
	{
		if (!GameController.pvpOn && !activeStopwatch.IsRunning && !(parentPlayer == null) && !(parentPlayer.health == null) && !parentPlayer.health.deathProof.CurrentValue && parentPlayer.health.CurrentHealthValue <= givenAtkInfo.damage && parentPlayer.health.CurrentShieldValue < givenAtkInfo.damage && !parentPlayer.health.GuardNextAtk && Random.value < ignoreChance)
		{
			ignoreChance *= 0.5f;
			parentPlayer.StartCoroutine(StartDeathProof(parentPlayer));
		}
	}
	private void SetItemBarStatus()
	{
		if (itemHeld)
		{
			if (activeStopwatch.IsRunning)
			{
				UpdateItemBar(ItemStatusBar.ItemState.Active);
			}
			else
			{
				UpdateItemBar(ItemStatusBar.ItemState.Ready);
			}
		}
	}
	private void SetDeathProofStatus(Player givenPlayer, bool givenStatus)
	{
		if (itemHeld && givenPlayer != null && givenPlayer.health != null)
		{
			givenPlayer.health.deathProof.Modify(deathProofMod, givenStatus);
		}
	}
	private IEnumerator StartDeathProof(Player givenPlayer)
	{

	{
		activeStopwatch.IsRunning = true;
		SetItemBarStatus();
		SetDeathProofStatus(givenPlayer, givenStatus: true);
		while (activeStopwatch.IsRunning)
		{
			yield return null;
		}
		SetItemBarStatus();
		SetDeathProofStatus(givenPlayer, givenStatus: false);
	}
}
