using System.Collections;
public class InvulnerableOnMultiHurt : OnTakeDamageItem
{
	public static string staticID = "InvulnerableOnMultiHurt";
	private int hurtCounter;
	private int activateHurtCount = 3;
	private ChaosQuickStopwatch hurtStopwatch = new ChaosQuickStopwatch(3f);
	private ChaosQuickStopwatch durationStopwatch = new ChaosQuickStopwatch(3f);
	private ChaosQuickStopwatch cdStopwatch = new ChaosQuickStopwatch(30f);
	private bool itemHeld;
	public InvulnerableOnMultiHurt()
	{
		ID = staticID;
		category = Category.Defense;
		activateOnActual = true;
	}
	public override void Activate()
	{
		base.Activate();
		itemHeld = true;
		SetItemBarStatus();
	}
	public override void Deactivate()
	{
		base.Deactivate();
		itemHeld = false;
		SetItemBarStatus();
	}
	private void SetItemBarStatus()
	{
		if (!itemHeld)
		{
			RemoveFromItemBar();
		}
		else if (durationStopwatch.IsRunning)
		{
			UpdateItemBar(ItemStatusBar.ItemState.Active);
		}
		else if (cdStopwatch.IsRunning)
		{
			UpdateItemBar(ItemStatusBar.ItemState.Disabled);
		}
		else
		{
			UpdateItemBar(ItemStatusBar.ItemState.Ready);
		}
	}
	public override void OnTakeDamageActual(AttackInfo givenAtkInfo, Entity givenEnt)
	{
		if (cdStopwatch.IsRunning || parentPlayer == null || givenAtkInfo == null || givenAtkInfo.damage <= 0)
		{
			return;
		}
		if (!hurtStopwatch.IsRunning)
		{
			hurtCounter = 1;
			hurtStopwatch.IsRunning = true;
			return;
		}
		hurtCounter++;
		if (hurtCounter < activateHurtCount)
		{
			hurtStopwatch.IsRunning = true;
			return;
		}
		hurtCounter = 0;
		hurtStopwatch.IsRunning = false;
		parentPlayer.health.SetInvulnerabilityDuration(durationStopwatch.Delay);
		parentPlayer.StartCoroutine(StartTimers());
	}
	private IEnumerator StartTimers()
	{
		durationStopwatch.IsRunning = true;
		cdStopwatch.IsRunning = true;
		SetItemBarStatus();
		while (durationStopwatch.IsRunning)
		{
			yield return null;
		}
		SetItemBarStatus();
		while (cdStopwatch.IsRunning)
		{
			yield return null;
		}
		SetItemBarStatus();
	}
}
