		{
			if (item.GetValue<float>("kbFieldStr") <= 40f && item.GetValue<float>("kbFieldStr") > 0f)
			{
				item.AddMod("kbFieldStr", knockbackUpMod);
			}
		}
	}
	public override void Deactivate()
	{
		List<StatData> allStatData = StatManager.GetAllStatData("Skills", parentSkillCategory);
		foreach (StatData item in allStatData)
		{
			item.RemoveMod("kbFieldStr", knockbackUpMod.ID);
		}
