using UnityEngine;
public class NevesAura : MonoBehaviour
{
	private static GameObject prefab;
	public GameObject[] auraObjArray;
	private Player parentPlayer;
	private GameObject curAuraObj;
	private bool isVisible = true;
	private bool isActive;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Effects/NevesAura.prefab"));
	public static NevesAura Create(Player givenPlayer, Transform givenTrans, ElementType givenEle)
	{
		NevesAura nevesAura = Globals.ChaosInst<NevesAura>(Prefab, givenTrans, givenTrans.position);
		nevesAura.parentPlayer = givenPlayer;
		nevesAura.Initialize(givenEle);
		return nevesAura;
	}
	private void Initialize(ElementType givenEle)
	{
		for (int num = auraObjArray.Length - 1; num >= 0; num--)
		{
			auraObjArray[num].SetActive(value: false);
		}
		switch (givenEle)
		{
		case ElementType.Fire:
			curAuraObj = auraObjArray[0];
			break;
		case ElementType.Air:
			curAuraObj = auraObjArray[1];
			break;
		case ElementType.Earth:
			curAuraObj = auraObjArray[2];
			break;
		case ElementType.Lightning:
			curAuraObj = auraObjArray[3];
			break;
		case ElementType.Water:
			curAuraObj = auraObjArray[4];
			break;
		case ElementType.Chaos:
			curAuraObj = auraObjArray[5];
			break;
		case ElementType.Neutral:
			break;
		}
	}
	private void Update()
	{
		if (parentPlayer == null || parentPlayer.spriteRenderer == null)
		{
			Reset();
		}
		else if (isVisible && !parentPlayer.spriteRenderer.enabled)
		{
			isVisible = false;
			if (curAuraObj != null)
			{
				curAuraObj.SetActive(value: false);
			}
		}
		else if (!isVisible && parentPlayer.spriteRenderer.enabled)
		{
			isVisible = true;
			SetStatus(isActive);
		}
	}
	public void SetStatus(bool givenStatus)
	{
		isActive = givenStatus;
		if (curAuraObj != null)
		{
			curAuraObj.SetActive(givenStatus);
		}
	}
	public void Reset()
	{
		if (gameObject != null)
		{
			Object.Destroy(gameObject);
		}
	}
}
