using UnityEngine;
public class PortableTreasure : Item
{
	public static string staticID = "PortableTreasure";
	private int currentValue;
	private int initialLoop;
	private int initialTier;
	private int initialStage;
	private int currentLoop;
	private int currentTier;
	private int currentStage;
	protected override string ExtraInfo
	{
		get
		{
			SetCurrentValue();
			return currentValue.ToString();
		}
	}
	public PortableTreasure()
	{
		ID = staticID;
		category = Category.Misc;
		destroyOnDrop = true;
	}
	public override void Activate()
	{
		initialLoop = GameController.loopCount;
		initialTier = GameController.tierCount;
		initialStage = GameController.stageCount;
	}
	public override void Deactivate()
	{
		if (SetParentAsPlayer() && !parentPlayer.IsDead)
		{
			Vector2 vector = parentPlayer.transform.position;
			parentPlayer.newItemNoticeUI.Display(TextManager.GetItemName(ID), IconManager.GetItemIcon(ID), null, isSkill: false, isSignature: false, isEmpowered: false, acquired: false);
			SoundManager.PlayWithDistAndSPR("CeramicBreak", vector);
			if (Globals.InGameScene(string.Empty))
			{
				SetCurrentValue();
				LootManager.DropGold(vector, Mathf.Min(1000, currentValue * 50));
				LootManager.DropPlat(vector, Mathf.Min(50, currentValue * 5));
				LootManager.DropHealth(vector, Mathf.Min(5, currentValue));
			}
		}
	}
	private void SetCurrentValue()
	{
		currentLoop = GameController.loopCount - initialLoop;
		currentTier = GameController.tierCount - initialTier;
		currentStage = GameController.stageCount - initialStage;
		currentValue = Mathf.Max(0, currentLoop * 9 + currentTier * 3 + currentStage);
		currentValue = Mathf.Min(20, currentValue);
	}
}
