using System.Linq;
public class RandomExplosiveBarrels : Item
{
	public static string staticID = "RandomExplosiveBarrels";
	private ExplosiveBarrelDeco explosiveBarrelDeco;
	private BoolVarStatMod ignorePlayerMod;
	private NumVarStatMod stunMod;
	public RandomExplosiveBarrels()
	{
		ID = staticID;
		category = Category.Misc;
		isCursed = true;
		hubOnly = true;
		explosiveBarrelDeco = new ExplosiveBarrelDeco();
		ignorePlayerMod = new BoolVarStatMod(ID, newModValue: true);
		stunMod = new NumVarStatMod(ID, 0.75f, 10, VarStatModType.Multiplicative);
	}
	public override void Activate()
	{
		SetModStatus(givenStatus: true);
	}
	public override void Deactivate()
	{
		SetModStatus(givenStatus: false);
	}
	private void SetModStatus(bool givenStatus)
	{
		ExplosiveBarrel.ignorePlayerStat.Modify(ignorePlayerMod, givenStatus);
		Decorator[] array = Decorator.TileSetDecorators.Values.ToArray();
		if (givenStatus)
		{
			for (int i = 0; i < array.Length; i++)
			{
				array[i].globalDecorations0.Add(explosiveBarrelDeco);
			}
		}
		else
		{
			for (int j = 0; j < array.Length; j++)
			{
				array[j].globalDecorations0.Remove(explosiveBarrelDeco);
			}
		}
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (player != null)
			{
				player.health.hitStunModifierStat.Modify(stunMod, givenStatus);
			}
		}
	}
}
